import java.util.Scanner;
public class SecureJavaAPIExample {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Introduce la URL: ");
        String urlInput = scanner.nextLine();
        // Validar la URL antes de usarla para evitar vulnerabilidades
        if (urlInput != null && urlInput.startsWith("http://") || urlInput.startsWith("https://")) {
            try {
                URL url = new URL(urlInput);
                URLConnection connection = url.openConnection();
                BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }
                reader.close();
            } catch (Exception e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("URL no válida. Por favor, asegúrate de que comience con http:// o https://.");
